1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM = 25;
4	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: COMPONENT_BASE_PREMIUM,
10	  moonstone: COMPONENT_BASE_PREMIUM,
11	};
12	const COMPONENT_BLOCK_SIZE = 3;
13	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
14	const CURSED_SURCHARGE_RATE = 0.5;
15	
16	type Item = {
17	  type: string;
18	  material?: string;
19	  enchantmentLevel?: number;
20	  cursed?: boolean;
21	};
22	
23	type Step = {
24	  op: string;
25	  items: Item[];
26	};
27	
28	type Scenario = {
29	  customer: { yearsWithMHPCO: number };
30	  steps: Step[];
31	};
32	
33	type QuoteResult = {
34	  premium: number;
35	};
36	
37	type ScenarioOutput = {
38	  results: QuoteResult[];
39	};
40	
41	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
42	  sameTypeItems.length === COMPONENT_BLOCK_SIZE;
43	
44	const groupByType = (items: Item[]): Item[][] => {
45	  const groups = new Map<string, Item[]>();
46	  for (const item of items) {
47	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
48	  }
49	  return [...groups.values()];
50	};
51	
52	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
53	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
54	  return sameTypeItems.reduce(
55	    (total, item) => total + BASE_PREMIUM_BY_ITEM_TYPE[item.type],
56	    0,
57	  );
58	};
59	
60	const basePremiumForItems = (items: Item[]): number =>
61	  groupByType(items).reduce(
62	    (total, group) => total + basePremiumForGroup(group),
63	    0,
64	  );
65	
66	const itemSurchargesForItems = (items: Item[]): number =>
67	  items.reduce(
68	    (total, item) =>
69	      total +
70	      (item.cursed
71	        ? BASE_PREMIUM_BY_ITEM_TYPE[item.type] * CURSED_SURCHARGE_RATE
72	        : 0),
73	    0,
74	  );
75	
76	const premiumBeforeProcessingFee = (items: Item[]): number => {
77	  const basePremium = basePremiumForItems(items);
78	  return (
79	    basePremium +
80	    itemSurchargesForItems(items) +
81	    basePremium * FIRST_INSURANCE_SURCHARGE_RATE
82	  );
83	};
84	
85	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
86	  results: scenario.steps.map((step) => ({
87	    premium: Math.ceil(premiumBeforeProcessingFee(step.items) + PROCESSING_FEE),
88	  })),
89	});
